"use strict";

// Planner: turns a command into a list of proposed actions using Claude tool-use.
// It does NOT execute — it returns the planned actions (with previews) for the
// approval step. Content (slides/paragraphs) is generated by Claude as the tool
// input; executors render it deterministically.

const registry = require("./registry");
const llm = require("../llm");
const { agentSystemPrompt } = require("../prompts");

// Returns { actions: [{ type, input, summary }], text }
async function plan({ lang, catName, persona, memory, instruction, commandText, allowedTypes, signal }) {
  const tools = registry.toolSchemas(allowedTypes);
  const parts = [];
  if (instruction) parts.push(instruction.trim());
  parts.push(`Kullanıcının komutu: "${String(commandText || "").trim()}"`);
  const userText = parts.join("\n\n");

  const { text, toolUses } = await llm.callWithTools({
    system: agentSystemPrompt(lang, catName, persona, memory),
    userText,
    tools,
    maxTokens: 4096,
    think: false,
    signal,
  });

  const actions = [];
  for (const tu of toolUses) {
    const executor = registry.get(tu.name);
    if (!executor) continue;
    let summary = tu.name;
    try {
      const preview = await executor.preview(tu.input);
      summary = (preview && preview.summary) || summary;
    } catch {}
    actions.push({ type: tu.name, input: tu.input, summary, approval: executor.approval });
  }

  return { actions, text };
}

module.exports = { plan };
